export const BRANCH_REEL_EXCERPTS = LOCAL_REEL_POSTERS.slice(0, 6).map((reel) => {
  const caption = cleanBranchReelCaption(reel.caption).replace(/\s+/g, " ").trim();
  return caption.length > 120 ? `${caption.slice(0, 117).trimEnd()}…` : caption;
});
